def settle(results, failures, policy, retry):
    """Decide what a lead does with a partial result set.

    results  -- list of (subtask, value) pairs that came back
    failures -- list of subtask names whose worker raised
    policy   -- "fail", "retry_then_degrade" or "escalate", chosen before the fan-out
    retry    -- retry(subtask) runs that subtask's worker once more; it returns a value or raises

    Returns (kept, note): the (subtask, value) pairs to synthesise from, and a note for the answer (or None).
    """
    if policy not in ("fail", "retry_then_degrade", "escalate"):
        raise ValueError(f"unknown partial-failure policy {policy!r}")
    if not failures:
        return list(results), None
    if policy == "fail":
        raise RuntimeError(f"{len(failures)} of {len(results) + len(failures)} subtasks failed")
    if policy == "escalate":
        return list(results), "ESCALATED: " + ", ".join(sorted(failures))
    kept, missing = list(results), []
    for subtask in failures:
        try:
            kept.append((subtask, retry(subtask)))
        except Exception:
            missing.append(subtask)
    return kept, ("MISSING: " + ", ".join(sorted(missing))) if missing else None
